# --- 안 나눈 테스트 ---

@DisplayName("주문을 생성하면 총 금액이 계산된다")
@Test
void createOrder() {
    CafeKiosk cafeKiosk = new CafeKiosk();
    cafeKiosk.add(new Americano());
    cafeKiosk.add(new Latte());
    Order order = cafeKiosk.createOrder(LocalDateTime.of(2026, 9, 9, 11, 0));
    assertThat(order.calculateTotalPrice()).isEqualTo(8500);
    assertThat(order.getBeverages()).hasSize(2);
}

$ ./gradlew test --tests CafeKioskTest

CafeKioskTest > 주문을 생성하면 총 금액이 계산된다 PASSED

#   통과한다

#   그런데 어느 줄이 검증 대상인가
#   add 인가 createOrder 인가 calculateTotalPrice 인가

# --- 나눈 테스트 ---

@DisplayName("주문을 생성하면 담긴 음료의 총 금액이 계산된다")
@Test
void createOrder() {
    // given
    CafeKiosk cafeKiosk = new CafeKiosk();
    cafeKiosk.add(new Americano());
    cafeKiosk.add(new Latte());
    LocalDateTime 영업중 = LocalDateTime.of(2026, 9, 9, 11, 0);

    // when
    Order order = cafeKiosk.createOrder(영업중);

    // then
    assertThat(order.calculateTotalPrice()).isEqualTo(8500);
}

CafeKioskTest > 주문을 생성하면 담긴 음료의 총 금액이 계산된다 PASSED

#   검증 대상이 createOrder 인 게 보인다

#   그리고 hasSize(2) 를 뺐다
#   그건 다른 테스트다  (7.1절)

# --- 숫자에 이름을 붙이기 전 ---

@Test
void vipDiscount() {
    assertThat(DiscountCalculator.calculate(10000, 3)).isEqualTo(8500);
}

DiscountCalculatorTest > vipDiscount() PASSED

#   3 이 뭔가

# --- 붙인 뒤 ---

@DisplayName("VIP 회원은 15퍼센트 할인을 받는다")
@Test
void vipDiscount() {
    // given
    int orderPrice = 10000;
    int vipLevel = 3;

    // when
    int discountedPrice = DiscountCalculator.calculate(orderPrice, vipLevel);

    // then
    assertThat(discountedPrice).isEqualTo(8500);
}

DiscountCalculatorTest > VIP 회원은 15퍼센트 할인을 받는다 PASSED

# --- 기대값을 계산식으로 쓰면 ---

// then
assertThat(discountedPrice).isEqualTo((int) (orderPrice * 0.85));

DiscountCalculatorTest > VIP 회원은 15퍼센트 할인을 받는다 PASSED

#   통과한다

#   그런데 프로덕션 코드의 할인율을 0.80 으로 바꾸고
#   테스트의 0.85 도 0.80 으로 바꾸면

// 프로덕션
VIP(3, 0.20);
// 테스트
assertThat(discountedPrice).isEqualTo((int) (orderPrice * 0.80));

DiscountCalculatorTest > VIP 회원은 15퍼센트 할인을 받는다 PASSED

#   이름은 15퍼센트인데 통과한다

#   테스트가 프로덕션 코드를 되풀이하면 아무것도 안 지킨다

#   상수로 두면

assertThat(discountedPrice).isEqualTo(8500);

